file.content:
sceneRef.current = scene;
scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);

const camera = new BABYLON.ArcRotateCamera("camera", Math.PI / 4, Math.PI / 3, 300, new BABYLON.Vector3(0, HEIGHT / 2, 0), scene);
camera.attachControl(canvas, true);

// Le clic gauche est réservé à la sélection rectangulaire (fenêtre de sélection, cf. plus
// bas) : on retire le bouton 0 des boutons d'orbite/pan de Babylon et on le remplace par le
// bouton du milieu (1), qui reprend l'orbite. Le clic droit garde le pan (comportement
// Babylon par défaut) en plus d'ouvrir le menu contextuel.
const pointersInput = camera.inputs.attached.pointers as BABYLON.ArcRotateCameraPointersInput | undefined;
if (pointersInput) {
  pointersInput.buttons = [1, 2];
  pointersInput.panningMouseButton = 2;
}

