input.content:
// Fenêtre de sélection (clic gauche + drag) : le mode « crossing » (drag vers la gauche) a un
// contour pointillé qui défile en continu façon « rails de train », impossible à obtenir avec
// les seules propriétés CSS de base — d'où ce module dédié au lieu d'un style inline.
@keyframes marchingAnts {
  to {
    background-position: 8px 0, 8px 8px, 0 8px, 0 0;
  }
}

.crossingBox {
  // 4 dégradés linéaires, un par bord, chacun un tiret répété qui glisse le long de son bord —
  // un `border` CSS classique ne sait pas animer un pointillé en boucle.
  background-image:
    linear-gradient(90deg, #fff 50%, transparent 50%),
    linear-gradient(90deg, #fff 50%, transparent 50%),
    linear-gradient(0deg, #fff 50%, transparent 50%),
    linear-gradient(0deg, #fff 50%, transparent 50%);
  background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
  background-size: 8px 1px, 8px 1px, 1px 8px, 1px 8px;
  background-position: 0 0, 0 100%, 0 0, 100% 0;
  animation: marchingAnts 0.35s linear infinite;
}

