  if (selectionDragStart) {
    const dx = evt.clientX - selectionDragStart.x;
    const dy = evt.clientY - selectionDragStart.y;
    if (!selectionDragging && Math.hypot(dx, dy) > SELECTION_BOX_DRAG_THRESHOLD_PX) {
