file.content:
// Fenêtre de sélection (clic gauche + drag) : le mode « crossing » (drag vers la gauche) a un
// contour pointillé qui défile en continu façon « rails de train », impossible à obtenir avec
// les seules propriétés CSS de base — d'où ce module dédié au lieu d'un style inline.
@keyframes marchingAnts {
  to {
    background-position: 8px 0, 8px 8px, 0 8px, 0 0;
  }
}

.crossingBox {
  // 4 dégradés linéaires, un par bord, chacun un tiret répété qui glisse le long de son bord —
  // un `border` CSS classique ne sait pas animer un pointillé en boucle.
  background-image:
    linear-gradient(90deg, #fff 50%, transparent 50%),
    linear-gradient(90deg, #fff 50%, transparent 50%),
    linear-gradient(0deg, #fff 50%, transparent 50%),
    linear-gradient(0deg, #fff 50%, transparent 50%);
  background-repeat: repeat-x, repeat-x, repeat-y, repeat-y;
  background-size: 8px 1px, 8px 1px, 1px 8px, 1px 8px;
  background-position: 0 0, 0 100%, 0 0, 100% 0;
  animation: marchingAnts 0.35s linear infinite;
}

input.content:
// Fenêtre de sélection (clic gauche + drag) : le mode « crossing » (drag vers la gauche) a un
// contour pointillé bleu qui défile en continu façon « rails de train ». Un `border` CSS
// classique ne sait pas animer un pointillé en boucle, et un unique élément avec 4 dégradés de
// fond en repeat-x/repeat-y déborde sur toute la surface plutôt que de rester sur les bords
// (chaque dégradé garde la taille de l'élément sur l'axe non répété) — on utilise donc 4 bandes
// fines, une par bord, chacune avec son propre dégradé tiled qui glisse.
@keyframes marchingAntsX {
  to { background-position: 8px 0; }
}
@keyframes marchingAntsY {
  to { background-position: 0 8px; }
}

$dash-color: #38bdf8; // bleu (accent), remplace le blanc précédent

.crossingBox {
  position: absolute;
  inset: 0;
}

.edgeX {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background-image: linear-gradient(90deg, $dash-color 50%, transparent 50%);
  background-size: 8px 1px;
  background-repeat: repeat-x;
  animation: marchingAntsX 0.35s linear infinite;
}

.edgeY {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background-image: linear-gradient(0deg, $dash-color 50%, transparent 50%);
  background-size: 1px 8px;
  background-repeat: repeat-y;
  animation: marchingAntsY 0.35s linear infinite;
}

.edgeTop { top: 0; }
.edgeBottom { bottom: 0; }
.edgeLeft { left: 0; }
.edgeRight { right: 0; }

