input.new_string:
// Fenêtre de sélection (clic gauche + drag) : le mode « crossing » (drag vers la gauche) a un
// contour pointillé bleu qui défile en boucle, dans le même sens tout autour du rectangle
// (horaire), façon « rails de train ». Un `border` CSS classique ne sait pas animer un pointillé
// en boucle, et un unique élément avec 4 dégradés de fond en repeat-x/repeat-y déborde sur toute
// la surface plutôt que de rester sur les bords (chaque dégradé garde la taille de l'élément sur
// l'axe non répété) — on utilise donc 4 bandes fines, une par bord, chacune avec son propre
// dégradé tiled qui glisse ; le sens de chaque bord est choisi pour que les 4 mises bout à bout
// tournent toutes horaire (haut → droite, droite → bas, bas → gauche, gauche → haut).
@keyframes marchingAntsForward {
  to { background-position: 8px 0; }
}
@keyframes marchingAntsBackward {
  to { background-position: -8px 0; }
}

$dash-color: #38bdf8; // bleu (accent), remplace le blanc précédent

.crossingBox {
  position: absolute;
  inset: 0;
}

.edge {
  position: absolute;
  background-image: linear-gradient(90deg, $dash-color 50%, transparent 50%);
  background-size: 8px 1px;
  background-repeat: repeat-x;
}

.edgeTop {
  top: 0; left: 0; right: 0; height: 1px;
  animation: marchingAntsForward 0.35s linear infinite; // vers +x (droite)
}
.edgeBottom {
  bottom: 0; left: 0; right: 0; height: 1px;
  animation: marchingAntsBackward 0.35s linear infinite; // vers -x (gauche)
}
.edgeLeft {
  top: 0; bottom: 0; left: 0; width: 1px;
  transform: rotate(90deg);
  transform-origin: top left;
  // Bande verticale obtenue en faisant pivoter une bande horizontale de sa propre longueur
  // (= hauteur du rectangle) plutôt qu'un second dégradé vertical : un seul jeu de keyframes
  // (`background-position` en x) suffit alors pour les 4 bords, sens garanti cohérent.
  width: var(--edge-height, 100%);
  height: 1px;
  animation: marchingAntsForward 0.35s linear infinite; // pivoté 90° : va vers le haut
}
.edgeRight {
  top: 0; right: 0; left: auto; width: 1px;
  transform: rotate(90deg);
  transform-origin: top right;
  width: var(--edge-height, 100%);
  height: 1px;
  animation: marchingAntsBackward 0.35s linear infinite; // pivoté 90° : va vers le bas
}

